// Procesar CSV manualmente (Made for Sport)
const csvText = items[0].json.data ?? items[0].json.body ?? items[0].json;
const lines = String(csvText).split(/\r?\n/);
const products = [];

function slugify(str) {
  return String(str || "")
    .toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

// Made for Sport no trae categorías, usamos "deportes" por defecto
// El usuario puede cambiarlas manualmente después
const defaultCategoryId = "deportes";

for (let i = 1; i < lines.length; i++) {
  const line = lines[i].trim();
  if (!line) continue;

  const fields = line.split(";");
  const cleanFields = fields.map((field) => field.replace(/"/g, "").trim());

  // Mapeo CSV Made for Sport:
  // column_0: Nombre
  // column_1: Precio
  // column_2: SKU (referencia)
  // column_3: EAN
  // column_4: Stock
  // column_5: Descripción (HTML)
  // column_6: URLs imágenes (separadas por coma)

  const name = cleanFields[0] || "";
  const price = parseFloat(cleanFields[1]) || 0;
  const refProveedor = cleanFields[2] || null;
  const ean = cleanFields[3] || null;
  const stock = parseInt(cleanFields[4], 10) || 0;
  const description = cleanFields[5] || "";
  const imagenesStr = cleanFields[6] || "";

  // Procesar múltiples imágenes
  const imagenes = imagenesStr
    .split(",")
    .map((url) => url.trim())
    .filter((url) => url.length > 0);

  // SKU interno: MF + referencia (sin variantes en Made for Sport)
  const skuInterno = `MF${refProveedor}`;
  const baseSlug = slugify(name);
  const slug = `${baseSlug}-${slugify(skuInterno)}`;

  products.push({
    json: {
      proveedor: "made_for_sport",
      ref_proveedor: refProveedor,
      ref_variante: null,
      ean,
      stock,
      name,
      description,
      price,
      imagenes, // Array de URLs
      slug,
      sku_interno: skuInterno,
      categoryId: defaultCategoryId,
      subcategory: "Made for Sport",
      marca: null,
      categoria: null,
      categoria_padre: null,
      color: null,
      talla: null,
      published: true,
      activo: true,
      visible_web: true,
    },
  });
}

return products;
